WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_average_base'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基期平均数', 'kp-xingce-data-average-base', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基期平均数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知现期总量和份数及其增速，倒推上一期的平均数。其公式和解法与“基期比重”完全一致。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "材料给出 2023 年的数据（分子分母的现期量及各自增长率），问 2022 年（上一年度）的平均数。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "基期平均数 = \\frac{A}{B} \\times \\frac{1+b}{1+a}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（A为分子现期量，a为其增速；B为分母现期量，b为其增速）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出拆解公式] --> B[第一步: 算出现期平均数 A/B]\nB --> C[拿着估算值去选项里排除离谱项]\nC --> D[第二步: 比较分子增速a和分母增速b]\nD -- a > b --> E[微调因子 < 1, 基期平均必然 小于 现期平均]\nD -- a < b --> F[微调因子 > 1, 基期平均必然 大于 现期平均]\nE --> G[在剩余选项中锁定答案]\nF --> G"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年全国投资额 11000 亿元，下降 10%。施工面积 830 万平方米，下降 5%。求2022年每平方米投资额？选项：A. 1210  B. 1320  C. 1430  D. 1550"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定结构：求投资额/面积。A=11000, a=-10%; B=830, b=-5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算现期：11000 ÷ 830 ≈ 13.25（即 1325）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定大小：a(-10%) < b(-5%)。分子降得更多，意味着今年平均数变小了，所以去年(基期)比今年大！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "选答案：找比 1325 大且接近的，锁定 C (1430)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "负数比较错误：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "和比重问题一样，负增长率比大小时，-10% 是小于 -5% 的。不要看着数字 10 觉得大就选反了方向。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看到求“去年的均价”、“去年的亩产”，条件反射写出两步法：算现期、判方向。绝不列两个基期量相除的蠢式子。"}]}]}$$ AS jsonb), NULL, '基期平均数的核心考点与实战推导。', category_node.id, CAST('["资料分析", "基期平均数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_average_base", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
